action.mutation:
mutation CreateScrapReason($payload: [ScrapReasonCreatePayloadInput!]!) {
  createScrapReason(payload: $payload) {
    id
    code
    controlPanel
    customer
    engineered
    internal
    supplier
  }
}

transforms.pre:
(

  $workunitId := $coalesce([$metadata.urlParameters.id,  $cuid()]);
  $scrapReasons := $components.Form1.data.scrapReasons;
  $workunitData := $components.Form1.data~>|$|
    {
      "changeoverStateListId": changeoverStateList.id,
      "productionStateListId": productionStateList.id,
      "idleStateListId": idleStateList.id,
      "disabledStateListId": disabledStateList.id,
      "maintenanceStateListId": maintenanceStateList.id,
      "otherStateListId": otherStateList.id,
      "scheduleGroupId": scheduleGroup.id,
      "workcenterId": workcenter.id,
      "ospType": workunitType = "ospType" ,
      "productionType": workunitType = "productionType" ,
      "concurrency":workunitType = "ospType" ? 99999
    },
    [
      "id",
      "changeoverStateList",
      "productionStateList",
      "idleStateList",
      "disabledStateList",
      "maintenanceStateList",
      "otherStateList",
      "scrapReasons",
      "workcenter",
      "workunitScrapReasons",
      "scheduleGroup",
      "originalScrapReasons",
      "workunitType"
    ]
  |;


  {
    "payload":{
      "where": { "id": $workunitId },
      "create": $workunitData,
      "update": $workunitData
    },
    "deleteScrapReasonsPayload":  [$components.Form1.data.workunitScrapReasons.edges.node.scrapReason.{
      "where":{
        "id":  $workunitId & "::" & id
      }
    }],
    "createScrapReasonsPayload": [$components.Form1.data.scrapReasons.{
      "create":{
        "id":  $workunitId & "::" & id,
        "scrapReasonId": id,
        "workunitId":  $workunitId
      }
    }]
  }
  
)

action.mutation:
mutation Mutation($payload: [WorkunitUpsertPayloadInput!]!, $deleteScrapReasonsPayload: [WorkunitScrapReasonDeletePayloadInput!]!, $createScrapReasonsPayload: [WorkunitScrapReasonCreatePayloadInput!]!) {
  upsertWorkunit(payload: $payload) {
    id
  }
  deleteWorkunitScrapReason(payload: $deleteScrapReasonsPayload) {
    id
  }
  createWorkunitScrapReason(payload: $createScrapReasonsPayload) {
    id
  }
}
